import { qualityAnalyzer } from '../../src/generation/quality-analyzer';

describe('QualityAnalyzer project scoring', () => {
  it('scores files independently instead of treating a project as one oversized module', async () => {
    const files = Array.from({ length: 24 }, (_, index) => ({
      path: `src/module-${index}.ts`,
      language: 'typescript',
      content: `/**
 * @generated by ORUS Builder
 * ═══════════════
 * @hierarchy ALFA
 * @component-hash module-${index}
 */
export const module${index} = (): number => ${index};`,
    }));

    const combined = await qualityAnalyzer.analyze({ code: files.map(file => file.content).join('\n') });
    const project = await qualityAnalyzer.analyzeProject(files);

    expect(project.success).toBe(true);
    expect(project.overallScore).toBeGreaterThan(combined.overallScore);
    expect(project.overallScore).toBeGreaterThanOrEqual(70);
    expect(project.summary).toContain('24 files analyzed');
  });
});
